func (t OauthType) ValueFromObject(ctx context.Context, in basetypes.ObjectValue) (basetypes.ObjectValuable, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributes := in.Attributes()

	clientNameAttribute, ok := attributes["client_name"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`client_name is missing from object`)

		return nil, diags
	}

	clientNameVal, ok := clientNameAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`client_name expected to be basetypes.StringValue, was: %T`, clientNameAttribute))
	}

	grantIdAttribute, ok := attributes["grant_id"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`grant_id is missing from object`)

		return nil, diags
	}

	grantIdVal, ok := grantIdAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`grant_id expected to be basetypes.StringValue, was: %T`, grantIdAttribute))
	}

	if diags.HasError() {
		return nil, diags
	}

	return OauthValue{
		ClientName: clientNameVal,
		GrantId:    grantIdVal,
		state:      attr.ValueStateKnown,
	}, diags
}

